    // Strict dead-space avoidance: post_residual in 1..10 is nearly unusable
    // (min item size 1, but small gaps rarely match future items) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is the best possible outcome.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (best-fit flavor with sharper curve).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins; penalize opening new bins when pressure is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 10.0 + 6.0 * pressure;
    } else {
        score -= 2.0 * pressure.min(10.0);
    }

    // Dead-space coupling with mean residual: if the fleet of open bins already
    // carries lots of slack, penalize adding more small waste.
    if post_residual > 0 && post_residual < 30 && mean_residual > 30.0 {
        score += 0.4 * (mean_residual - 30.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving awkward gaps.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match between post_residual and next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect fit for the next item: huge reward.
        if post == next {
            score -= 60.0;
        } else if post >= next {
            // Next item still fits: reward proportional to how tight the fit is.
            let slack = post - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if after the next item the bin is nearly full.
            if post - next <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item does NOT fit in this bin: penalize leaving a gap
            // slightly too small for the next item (dead space trap).
            let gap = next - post;
            if gap <= 10.0 {
                score += 20.0 + gap as f64;
            } else {
                score += 5.0;
            }
        }
    }

    // --- Relative tightness vs mean residual across open bins ---
    // Prefer bins whose post residual is well below the mean (compact fill).
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 10.0 * rel.max(-2.0).min(2.0);
    }

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Penalize tiny unusable remnants (dead space < 10) ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item leaves a large,
        // reusable residual AND no existing bin fits well; otherwise push
        // the score up so existing bins win.
        let base = 45.0
            - 0.15 * open_bins_count as f64
            - (item_size as f64 / bin_capacity as f64) * 20.0;
        // If this is a last-chance situation, make new bin unattractive.
        let last_chance = (fitting_bins_count == 1) as f64;
        score += base + last_chance * 25.0;
        // Late in the stream, prefer closing out open bins rather than
        // spawning new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (near-exact fill).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward using this bin
    // (chaining placements); otherwise mild penalty for blocking the successor.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins have large mean
    // residual but none fit well, or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / (bin_capacity as f64);
        // Penalize new bins when existing bins are tight (fragmentation low).
        score += 35.0 * (1.0 - fragmentation);
        // Slightly favor opening bins early (build capacity for future items).
        score -= 10.0 * (1.0 - progress);
        // Discard new-bin option if a decent fit exists elsewhere.
        if post_residual + item_size <= bin_capacity && fitting_bins_count > 0 {
            let best_gap = (bin_residual as f64 - item_size as f64);
            if best_gap < 15.0 {
                score += 60.0;
            }
        }
    }

    // Mild global pressure: many open bins -> prefer consolidating into them.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.004 * pr);

    // Quadratic coupling of post_residual with stream progress:
    // early on, prefer tight fills (low pr); later, waste matters more (bins are sunk cost)
    let prog_sq = progress * progress;
    score += pr * pr / cap * (0.5 + 1.5 * prog_sq);

    // Reward near-perfect fits smoothly (cubic shaping)
    let fill = 1.0 - pr / cap;
    score -= 20.0 * fill * fill * fill;

    // Lookahead: penalize if post_residual cannot host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let slack_ratio = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * fits_next * (1.0 - slack_ratio);
        score += 6.0 * (1.0 - fits_next) * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild preference for the tightest among many candidates via residual spread
        score += (fitting_bins_count as f64).ln() * pr * 0.05;
    }

    // Mean-residual coupling: avoid dumping into bins that deviate wildly from the mean
    let dev = (mean_residual - bin_residual as f64).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: score it relative to average waste it would incur
    if bin_residual == bin_capacity {
        let new_bin_base = cap - item_size as f64;
        score = new_bin_base * (1.0 + 0.004 * new_bin_base)
            + 12.0 * (1.0 - progress)
            - 6.0 * progress
            + (open_bins_count as f64) * 0.5;
        // discourage opening new bin when a decent fit exists elsewhere
        if next_item_size > 0 && new_bin_base >= next_item_size as f64 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of leftover space: leftover buckets of width 10.
    // Larger class index => more dead space => superlinear penalty.
    let class = (post_residual / 10) as f64; // 0..=10
    score *= 1.0 + 0.08 * class;

    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling (k=2): does the next item fit in the residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain-friendly bin: reward, extra if it's an exact harmonic match.
            score -= 10.0;
            if post_residual > 0 && post_residual % next_item_size == 0 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: residual is likely dead space; penalize.
            score += 0.15 * post_residual as f64;
        }
        // Small-residue class check: leftover < 10 is nearly unusable
        // (min item size historically 10) -> heavy penalty.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate (pristine bin): usually undesirable when alternatives exist,
    // but acceptable when nothing open fits or open bins are very fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0; // forced opening: neutral-ish
        } else {
            score += 25.0 + 0.3 * mean_residual + 2.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Slight preference for tighter fits overall (fraction-of-capacity coupling).
    score += 0.02 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harder (dead space): post_residual in (0, 10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }
    // Mild penalty on tight-but-nonzero residuals to prefer exact fits
    if post_residual > 0 && post_residual <= 5 {
        score += 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0 + 5.0;
        // but attractive if no fitting bins exist
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // last-chance bonus: only this bin can fit the item
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Lookahead coupling: prefer bins whose post_residual fits next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual alignment: prefer bins below mean residual (tighter packing)
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    // Progression: as stream advances, be slightly more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain match
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * slack; // prefer tight future fits
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.10 * gap;
        }
        // If next item is huge and only fits empty bins, discourage filling this bin
        if next_item_size > post_residual && next_item_size as f64 > mean_residual * 1.5 {
            score += 8.0;
        }
    }

    // Favor bins that are already relatively full (small residual before placement)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate calibration: opening a bin should only win when no
    // open bin offers a decent fit. Baseline penalty for fresh bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If mean residual across open bins is small (open bins are tight),
        // opening a new bin becomes more attractive.
        score -= 0.20 * mean_residual;
        // Few fitting bins -> new bin more acceptable
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild stream-phase adjustment: early on, be pickier (favor tight fits later too)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero (dead space).
    if post_residual > 0 {
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score += tight * 30.0;
    } else {
        // Perfect fill is highly desirable.
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.2 * (next_item_size as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); later, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 10.0 + 40.0 * progress - 8.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Existing bin: more attractive as the stream progresses.
        score -= 10.0 * progress;
    }

    // Global state coupling: penalize placements that diverge from mean residual
    // (keeps residual distribution balanced), scaled by number of open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 + (open_bins_count as f64) / 10.0);

    // Prefer filling larger items into bins with less residual headroom.
    score += 0.1 * (bin_residual as f64 - item_size as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;

    // Base: post residual, with smooth non-linear penalty on wasted space
    let mut score = pr;

    // Non-linear coupling: post residual squared normalized, modulated by stream progress.
    // Early in stream, tolerate larger residuals less (prefer tight fits to build good bins);
    // late in stream, dead space matters more since fewer chances to fill it.
    let dead_penalty = (norm_pr * norm_pr) * cap * (0.5 + progress);
    score += dead_penalty;

    // Smooth reward for near-perfect fits: bell-shaped bonus around small post_residual
    let tightness = (-norm_pr * 4.0).exp();
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // smoothly scaled by how full the placement leaves the bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr * 0.5);
    }

    // Lookahead coupling: reward if next item fits in the post residual (smooth decay)
    if next_item_size > 0 {
        let next_fits = (pr - next_item_size as f64) / cap;
        let bonus = (next_fits.max(-1.0) * 3.0).tanh();
        score -= 8.0 * bonus.max(0.0);
        // Penalize if post residual is just barely too small for next item (unusable sliver)
        let sliver = ((next_item_size as f64 - pr) / cap).exp();
        score += 6.0 * sliver * (1.0 - progress);
    }

    // Prefer bins with below-mean residual (tighter bins) — smooth coupling
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: bins whose leftover lies in a
    // "reusable" class (multiples of 10, or >= next item) are favored.
    let next = next_item_size as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward when the post residual can host the lookahead item.
    if next > 0.0 && next <= post {
        score -= 12.0 + 6.0 * (1.0 - post / cap);
    } else if next > 0.0 {
        // Penalize dead space that cannot fit the next item.
        score += 8.0 * (post / cap);
    }

    // Harmonic (modulo) class bonus: residual in {0, 10, 20, ...} classes
    // are highly reusable under common size distributions.
    let post_u = post_residual;
    if post_u == 0 {
        score -= 15.0; // perfect closure
    } else if post_u % 10 == 0 {
        score -= 6.0;
    } else if post_u % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0 * ((5 - (post_u % 5)) as f64) / 5.0;
    }

    // Integer-division threshold: classify residual into coarse buckets.
    let bucket = post_u / 20; // 0..5
    score -= match bucket {
        0 => 4.0,           // tiny residual: nearly full bin, good
        1 => 1.0,
        2 => 0.0,
        3 => -1.0,          // mid-size residual, still useful
        _ => -2.0,          // large residual: roomy bin
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, prefer tightening packing (small post residual).
    let crowd = open_bins_count as f64;
    score += 0.15 * crowd * (post / cap);

    // Mean residual coupling: if this bin's residual is far above mean,
    // it is a good "sponge" for large items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Early in the stream, be slightly more willing to keep bins tight;
    // later, prefer filling existing bins over opening new ones.
    if progress > 0.5 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = next > 0.0 && next > post && post > 0.0;
        if poor_fit || (fitting_bins_count == 0) {
            score -= 25.0; // open a new bin rather than fragment
        } else {
            score += 18.0; // discourage wasting a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (min item size is 10) are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Favor bins whose residual is close to the item (tight packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * 0.35;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // a new bin — reward it, especially under high open-bin pressure.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - next_tight / 100.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    // to preserve large gaps in other bins for future large items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: make opening a new bin only attractive when the
    // item is large relative to capacity or existing bins are very tight.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 50 { -10.0 } else { 10.0 };
        score += 8.0 + pressure * 0.2 + large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (perfect 2-item packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap * gap);
        // Exact match: strong bonus.
        if post_residual == next_item_size {
            score -= 45.0;
        }
        // Penalize leaving residual the next item cannot use at all.
        if post_residual > 0 && next_item_size > post_residual {
            score += 12.0;
        }
    } else {
        // Last item: prefer zero residual.
        score -= 40.0 / (1.0 + post_residual as f64);
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving less than average residual is good (denser packing).
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong preference to use it rather than open new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins can fit the item,
    // unless the item is huge and a fresh bin gives a great fit.
    if bin_residual == bin_capacity {
        let tight_fit = (item_size as f64 / bin_capacity as f64) > 0.85;
        if fitting_bins_count > 0 && !tight_fit {
            score += 30.0;
        }
        // Small penalty anyway to prefer reusing bins on ties.
        score += 1.0;
    }

    // Slight preference for bins with small residual before placement (tight fit).
    score += 0.10 * bin_residual as f64;

    // Late in the stream, be more conservative: favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 12.0 {
        score += 14.0 * (12.0 - dead) / 12.0;
    }

    // Lookahead: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item won't fit here: slight penalty if we leave large gap anyway
            score += 2.0;
        }
    } else {
        // Last item: strongly prefer minimal post_residual.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer filling existing ones over opening new.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= 3.0 * pressure.min(4.0);

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 8.0 * progress * fit_ratio;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already tight — prefer it.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev.max(0.0);
    score += 0.10 * (-dev).max(0.0);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_cost = 55.0
            + 30.0 * (open_bins_count as f64).ln().max(0.0)
            - 40.0 * progress
            - if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score = new_bin_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows super-linearly for large dead space.
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth coupling: late in the stream, dead space matters more (fewer
    // future chances to fill gaps), so scale the penalty by a smooth
    // progress-driven term.
    let late_factor = 0.5 + 0.5 * progress * progress;
    score += late_factor * (pr / cap) * 10.0;

    // Reward tight fits (small post_residual relative to capacity) with a
    // smooth inverse term.
    score -= 8.0 * (1.0 - pr / cap).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 6.0 * (1.0 - slack / cap);
        } else {
            score += 0.02 * (nxt - pr);
        }
    }

    // Slight preference for filling bins that deviate from the mean residual
    // (converge residuals to reduce fragmentation), smooth quadratic term.
    score += 0.01 * (mean_residual - pr) * (mean_residual - pr) / (1.0 + open_bins_count as f64);

    // New-bin candidate: mild bias toward reusing open bins early,
    // toward opening fresh bins late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 5.0 - 10.0 * progress * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction classes
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Reward near-perfect fits: post_residual in the lowest "harmonic band"
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else if post_residual <= 5 {
        score -= 60.0;   // near-perfect: dead space negligible
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Penalize "awkward" dead space via modulo classes:
    // post_residual in [1..9] mod 10 bands are hard to fill by small items
    let mod_class = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - mod_class as f64 / 10.0);
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // chain fit: excellent
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * usage;
            // harmonic penalty: leftover after next item in a bad band
            let chain_left = post_residual - next_item_size;
            if chain_left > 0 && chain_left < 10 {
                score += 15.0 * (1.0 - chain_left as f64 / 10.0);
            }
        } else {
            // next item cannot use this bin's leftover: leftover likely dead
            score += 10.0 + 0.2 * (post_residual as f64 - 0.0).min(60.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the one with least post residual (best fit)
        score += 0.0; // base post_residual ordering already handles this
    }

    // New-bin candidate (empty bin): make it attractive only when current bins
    // would create bad dead space. Empty bin residual = capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when item is large relative to capacity
        // and few bins fit it (fragmentation risk elsewhere)
        let item_frac = item_size as f64 / cap;
        score = 0.35 * cap - 30.0 * item_frac;
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
        // late in stream, slightly favor consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64 * (post_frac);

    // Mean residual coupling: if this bin is far below mean residual,
    // it's already fragmented; penalize slightly
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

