    // Tightness reward, slightly amplified for large items.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let tight_w = if item_size >= 50 { 24.0 } else { 18.0 };
    score -= tight_w * tightness;

    // Open-bin pressure grows over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.55 + 0.45 * progress);
    score += pressure * 0.35;

    // Last-chance bin: only bin that fits — using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0 + 0.55 * open_bins_count as f64;
    }

    // Lookahead: exact or near-exact chain fits are strongly favored.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        let chain_bonus = if next_tight == 0.0 { 22.0 } else { 14.0 * (1.0 - next_tight / 100.0) };
        score -= chain_bonus;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item; worse when gap is large.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.08 * gap;
    }

    // Mean-residual coupling: preserve large gaps for future large items,
    // but only when the next item is small (large next items want big gaps used).
    let below_mean = (bin_residual as f64) < mean_residual;
    if next_item_size >= 50 {
        if below_mean { score -= 3.0; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 7.0; } else { score += 4.0; }
    }

    // New-bin candidate: attractive only for large items, tight bins,
    // or when open bins have poor fit for the item.
    if bin_residual == bin_capacity {
        let best_open_fit = if fitting_bins_count > 0 { 1 } else { 0 };
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        // Large items open fresh bins readily; small items should fill existing bins.
        if item_size >= 60 {
