        } else if item_size >= 40 {
            new_bin_score -= 4.0;
        } else {
            new_bin_score += 12.0;
        }
        // If no open bin fits, the new bin is the real candidate — soften penalty.
        if best_open_fit == 0 {
            new_bin_score -= 20.0;
        }
        // Early stream: cheaper to open bins and build a good residual pool.
        if progress < 0.3 {
            new_bin_score -= 5.0 * (0.3 - progress) / 0.3;
        }
        score += new_bin_score;
    }

    score
}

