        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    } else {
        // Open-bin refinement: when this bin's post-residual is a dead gap for
        // the next item AND a sibling bin can host the next item, penalize
