        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size
            && fitting_bins_count >= 2 {
            score += 2.5;
        }
        // Reward bins whose residual stays exactly reusable by the next item
        // even if this placement isn't the tightest.
        if next_item_size > 0 && post_residual == next_item_size && bin_residual != bin_capacity {
            score -= 4.0;
        }
        // Mutation: two-step lookahead — if this placement leaves a residual
        // that cannot host the next item, but a residual of (post_residual +
        // next_item_size) would be fully consumed by the pair, prefer bins
