            let stranded = post_residual as f64 / bin_capacity.max(1) as f64;
            if stranded < 0.12 {
                score += 3.0 * (0.12 - stranded) / 0.12;
            }
        }
        // Mutation: exact-fit preference when the pool is rich — with many
        // fitting bins, prioritize the tightest compaction more aggressively.
        if fitting_bins_count >= 3 && tightness > 0.9 {
