    // Strong reward for perfect 2-step match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Partial lookahead reward: next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64 / post_residual as f64) * 20.0;
    } else if next_item_size > 0 {
        // Dead space penalty scaled by how far next item overshoots.
        let overshoot = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += overshoot * 0.8;
    }

    // Reward tight fits relative to current bin residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Penalize bins whose residual deviates upward from the mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1; // slight reward for below-mean (tighter) bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Discourage opening a new bin when existing bins fit decently.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus penalty unless current item is large
        // and would leave little useful residual anywhere.
        score += 55.0 - (item_size as f64 / bin_capacity as f64) * 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
