        }
        if fitting_bins_count == 0 {
            new_bin_score -= 26.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 5.5 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            // Only fitting bin leaves a useless sliver — fresh bin competes.
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.0 - 0.35 * post_residual as f64;
            }
            // Prefer fresh bin when the best open fit strands a large fraction
            // of its residual and the next item could still use that residual.
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.0 * item_ratio;
                if next_item_size > 0 && post_residual >= next_item_size {
                    new_bin_score -= 3.0;
                }
            }
            // If the leftover sliver cannot host the next item, fresh bin is
            // doubly attractive: the residual is truly stranded.
            if next_item_size > 0 && post_residual < next_item_size && post_residual < 12 {
                new_bin_score -= 4.5;
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.0 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 4.5 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    } else {
        // Complementary term: mildly favor keeping large-residual bins intact
        // for future items when the current fit is loose.
        if next_item_size > 0 && post_residual > next_item_size * 2 && bin_residual > 40 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly or nearly accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: this bin will be exactly filled by the
            // next item -> extremely desirable.
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this placement; prefer tighter matches
            // (smaller leftover after the pair).
            let pair_leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * pair_leftover;
        } else {
            // Next item cannot use the leftover: dead-space penalty scaled
            // by how large the stranded gap is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Compare post_residual against the mean residual: placing into a bin
    // that ends far below the mean wastes the "spread" of open bins.
    let drift = post_residual as f64 - mean_residual;
    score += 0.25 * drift;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, mildly favor tight fits.
        score += 0.1 * (fitting_bins_count as f64 - 1.0);
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Penalize wasting a nearly-empty (fresh) bin on a small item unless
    // the lookahead justifies it (handled above); this makes the new-bin
    // candidate only win when open bins are truly poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * item_size as f64;
    }

    // Late-stream consolidation: as the stream progresses, prefer closing
    // bins tightly rather than spreading across many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: sharpen low-residual bands, with a finer split
    // in the wasteful 10-29 region where most residual accumulates.
    if post_residual < 10 {
        score += 70.0;
    } else if post_residual < 16 {
        score += 33.0;
    } else if post_residual < 24 {
        score += 26.0;
    } else if post_residual < 30 {
        score += 9.0;
    } else if post_residual < 45 {
        score += 1.5;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 92.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 8 {
        score -= 13.5;
    }

    // Tightness reward, amplified for large items; quadratic flavor retained.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let tight_w = if item_size >= 50 { 34.0 } else { 21.0 };
    score -= tight_w * tightness + 6.5 * tightness * tightness;

    // Open-bin pressure grows over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.55 + 0.45 * progress);
    score += pressure * 0.35;

    // Last-chance bin: only bin that fits — using it avoids a new bin.
    // Strengthen the reward when the resulting sliver is still useful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let sliver = post_residual as f64;
        let sliver_bonus = if sliver < 12.0 { 15.0 } else { 21.0 };
        score -= sliver_bonus + 0.55 * open_bins_count as f64;
    }

    // Lookahead: exact or near-exact chain fits are strongly favored.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        let chain_bonus = if next_tight == 0.0 {
            37.0
        } else if next_tight <= 10.0 {
            25.5 * (1.0 - next_tight / 110.0)
        } else {
            14.5 * (1.0 - next_tight / 100.0)
        };
        score -= chain_bonus;
        if next_tight > 0.0 && next_tight <= 25.0 && next_item_size >= 30 {
            score -= 3.5;
        }
        if next_item_size >= 60 && next_tight <= 15.0 {
            score -= 6.5;
        }
        // Two-step chain: if the residual after the next item is tiny too,
        // this bin is a rare triple-fit anchor — reward harder.
        let two_step = next_tight;
        if two_step >= 0.0 && two_step <= 6.0 && next_item_size >= 45 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item; scale penalty with gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 9.5 + 0.11 * gap;
        if gap <= 4.0 {
            score -= 3.0;
        }
    }

    // Mean-residual coupling with variance awareness: when residual spread is
    // low (pool is homogeneous), large gaps are scarcer — protect them more.
    let below_mean = (bin_residual as f64) < mean_residual;
    if next_item_size >= 50 {
        if below_mean { score -= 4.0; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 9.5; } else { score += 4.5; }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 18.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 5.5;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 26.0;
        } else {
