            }
            // If the best open fit would strand a large fraction of its
            // residual while a fresh bin would be nearly full, prefer fresh.
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.0 * item_ratio;
            }
