    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let huge_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let mut new_bin_score = 8.0
            - 20.0 * fragmentation
            - 10.0 * progress
            + 0.05 * open_bins_count as f64;
