    let p2 = progress * progress;
    let p3 = p2 * progress;

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early in the stream, residuals are cheap (bins are fresh); late in the
    // stream, wasting space is costly, so the residual penalty grows.
    let residual_weight = 1.0 + 1.5 * p2 + 1.0 * p3;
    score = pr * residual_weight;

    // Smooth superlinear penalty on large dead space (wasted capacity),
    // amplified as the stream progresses.
    let waste = pr_norm * pr_norm * pr_norm;
    score += 60.0 * waste * (0.5 + progress);

    // Reward tight fits: item_size close to bin_residual leaves small
    // post_residual; add a smooth bonus proportional to fill ratio.
