    } else if post_residual < 20 {
        score += 34.0 + (20.0 - pr) * 1.4;
    } else if post_residual < 30 {
        score += 9.5 + (30.0 - pr) * 0.5;
    } else if post_residual < 45 {
        score += 1.5;
    }

    // Tightness reward: linear + quadratic, amplified for large items.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let tight_w = if item_size >= 50 { 36.0 } else if item_size >= 25 { 22.0 } else { 15.0 };
    score -= tight_w * tightness + 6.5 * tightness * tightness;
    if tightness > 0.85 {
        score -= 14.0 * (tightness - 0.85);
    }

