pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are preferred (waste quantization).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-perfect fits strongly (post residual in low harmonic band).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Modulo-10 class penalty: residues like 1..9 (non-multiples of 10) are
    // harder to fill later for typical item sizes; penalize awkward classes.
    let r10 = post_residual % 10;
    if r10 != 0 && post_residual > 0 {
        score += (r10 as f64) * 0.6;
    }
    // Multiples of 10 residuals are reusable "harmonic slots".
    if r10 == 0 && post_residual >= 10 {
        score -= 6.0;
    }

    // Integer-division thresholds: how many items of the current size could
    // still fit conceptually — tighter class means better packing.
    let k_fit = bin_residual / item_size.max(1);
    if k_fit >= 2 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item exactly matches post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // dead space relative to lookahead; mild penalty scaled by gap
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
        // Harmonic divisibility: next item divides residual evenly.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are
    // heavily fragmented (mean residual small) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / cap;
        // New bins are penalized by default; discount when fragmentation low.
        score += 25.0 - 30.0 * (1.0 - fragmentation.min(1.0)) - 10.0 * (1.0 - progress);
        // If next item is huge, a fresh bin may be valuable.
        if next_item_size >= 70 {
            score -= 10.0;
        }
    }

    // Mild pressure against proliferating bins.
    score += open_bins_count as f64 * 0.15;

    score
}

