    if next_item_size >= 50 {
        if below_mean { score -= 4.5; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 10.0; } else { score += 4.5; }
    }

    // Dead-space ratio coupling — penalize stranded space with a
    // progressive (quadratic-flavored) ramp so mild stranding is tolerated
    // but heavy stranding is punished harder.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let strand_ratio = post_residual as f64 / bin_residual as f64;
        if strand_ratio > 0.55 {
            let excess = strand_ratio - 0.55;
            score += 5.5 * excess * (1.0 + 1.6 * excess)
                * (post_residual as f64 / 30.0).min(1.5);
        }
        // REFINED: absolute dead-space floor — even a modest ratio on a large
        // residual wastes real capacity; add a smooth quadratic term for
        // post-residuals in the awkward 15-35 band on big bins.
        if post_residual >= 15 && post_residual <= 35 && bin_residual >= 50 {
            let mid = 25.0;
            let dev = (post_residual as f64 - mid).abs();
            score += 0.35 * (1.0 - dev / 10.0).max(0.0);
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            // Only fitting bin leaves a useless sliver — fresh bin competes.
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            // Prefer fresh when best open fit would strand a large share.
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            // Fresh landing zone for a large next item in a small pool.
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            // If the next item cannot fit ANY open bin's residual after
            // this placement, a fresh bin preserves a full-capacity landing
            // pad — stronger with larger next item.
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            // NEW: fresh bin is valuable when the open-bin pool is bloated
            // with small residuals — opening fresh lets us close ranks.
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement can still fit a typical next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if this placement wastes space the next item could have used.
    if next_item_size > 0 && bin_residual >= next_item_size && post_residual < next_item_size {
        score += 15.0;
    }

    // Open bins pressure: fewer open bins preferred; discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish; only open new bin when fit is bad.
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.1;
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins below mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
