        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // NEW: late-stream consolidation — when few items remain, opening
            // a fresh bin is cheap only if the remaining stream can fill it;
            // otherwise prefer squeezing into open bins.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: next item exactly fills the residual after placement.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post residual -> excellent two-item packing.
        else if post_residual >= next_item_size {
            // Reward proportional to how tightly the next item nests.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - 0.35 * slack;
        }
        // Next item does not fit: penalize more when leftover is small-but-useless.
        else {
            let waste = post_residual as f64;
            if waste <= 10.0 {
                score -= 5.0; // tiny leftover is fine
            } else {
                score += 0.25 * (waste - 10.0);
            }
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 10.0;
    }

    // --- Relative-to-mean coupling ---
    // Bins with residual far above the mean are "loose"; prefer tighter bins
    // unless the lookahead match rewards them.
    let residual_f = post_residual as f64;
    if residual_f > mean_residual {
        score += 0.15 * (residual_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - residual_f).min(30.0);
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is good only when the item is large relative to
        // what open bins can absorb, or when no tight match exists elsewhere.
        score = post_residual as f64 + 8.0;
        if next_item_size > 0 && next_item_size >= post_residual {
            // A fresh bin can host both current and next item comfortably.
            if item_size + next_item_size <= bin_capacity {
                score -= 20.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // --- Stream progression: become more conservative late in the stream ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (residual_f / bin_capacity as f64);

    score
}

