    score += (bin_residual as f64 / cap) * (3.0 + 4.0 * progress);

    // New-bin candidate handling: penalize opening a new bin unless it is unavoidable
    // or the alternative fit is terrible (post_residual would be very small usage).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * mean_residual + 10.0 * progress;
