    if post_residual < 5 {
        score -= 8.0;
    } else if post_residual <= 10 {
        score -= 3.0;
    }

    // Penalize creating dead space larger than any typical item when many bins exist.
    if post_residual > 10 && post_residual < 20 && open_bins_count > 3 {
        score += 2.0;
    }

    score
}

