        }
        // Complementarity: reward leaving post_residual close to the pool's
        // mean residual minus the next item — steers residuals toward
        // self-consistent, reusable levels.
        if next_item_size > 0 && post_residual >= next_item_size {
            let target = (mean_residual - next_item_size as f64).abs();
            let closeness = (post_residual as f64 - target).abs();
            if closeness <= 6.0 {
                score -= 2.0 * (1.0 - closeness / 7.0);
            }
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation — a fresh bin is cheap only if the
            // remaining stream can fill it; otherwise squeeze into open bins.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk: fresh bin only attractive if the next
            // item could also live in it.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Mid-stream, large item with a thin fitting pool — a fresh bin
            // guarantees zero dead space for this item.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // early on, small residuals matter less; late, tight fits are crucial.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.6 * progress_coupling - 0.5 * pr * (1.0 - progress);

    // Reward near-perfect fits via smooth penalty on squared deviation from zero residual
    score += 0.35 * norm_pr * norm_pr * cap;

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual slightly (packing larger into emptier bins)
    score += 0.15 * (pr - mean_residual);

    // Lookahead: reward leaving space usable by next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.25 * gap;
        if pr >= next_item_size as f64 {
            score -= 3.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty on many open bins to discourage bin sprawl
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: neutral-ish baseline, penalized early, allowed late
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) - 8.0 * progress;
    }

    score
}

