pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap * 10.0).floor(); // 0..10 capacity-decile class

    // Reward post-residuals that fall into "harmonic" small classes (near-perfect fits)
    match post_residual {
        0 => score -= 50.0,
        1..=5 => score -= 25.0,
        6..=10 => score -= 12.0,
        _ => {}
    }

    // Modulo-10 arithmetic: leftovers divisible by 10 pair well with typical item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd/awkward leftovers are penalized mildly
    if post_residual % 2 == 1 && post_residual > 15 {
        score += 2.0;
    }

    // Integer-division threshold: leftover in [next_item_size, next_item_size+10] is ideal
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 20.0;
