    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        let chain_bonus = if next_tight == 0.0 {
            40.0
        } else if next_tight <= 10.0 {
            27.0 * (1.0 - next_tight / 110.0)
        } else {
            15.0 * (1.0 - next_tight / 100.0)
        };
        score -= chain_bonus;
        if next_tight > 0.0 && next_tight <= 25.0 && next_item_size >= 30 {
            score -= 3.5;
        }
        if next_item_size >= 60 && next_tight <= 15.0 {
            score -= 7.5;
        }
        // Two-step chain awareness.
        if post_residual >= next_item_size * 2 {
            let two_step = post_residual - next_item_size * 2;
            if two_step <= 12 {
                score -= 4.2 * (1.0 - two_step as f64 / 14.0);
            }
        }
        // Three-step chain probe for small items.
        if next_item_size <= 25 && post_residual >= next_item_size * 3 {
            let three_step = post_residual - next_item_size * 3;
            if three_step <= 6 {
                score -= 3.2 * (1.0 - three_step as f64 / 8.0);
            }
        }
        // Continuous chain-depth probe.
        let depth = post_residual / next_item_size;
        if depth >= 2 {
            let cap = if next_item_size <= 15 { 5.0 } else { 4.0 };
            score -= (depth.min(cap) as f64 - 1.0) * 2.4;
        }
        // Exact multi-fill: post_residual is an exact multiple of the next item.
        if post_residual % next_item_size == 0 {
            let copies = post_residual / next_item_size;
            if copies >= 2 {
                score -= 3.0 + 1.2 * copies.min(5) as f64;
            }
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item; scale penalty with gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.12 * gap;
        if gap <= 4.0 {
            score -= 3.0;
        }
        if post_residual <= 3 {
            score += 2.0;
        } else if gap > 12.0 {
            score += 0.09 * gap;
        }
        // Soften if the sliver could host a later typical item.
        let typical = mean_residual.max(1.0);
        if post_residual as f64 >= typical * 0.9 {
            score -= 2.8;
        }
    }

    // Mean-residual coupling with variance awareness.
    let below_mean = (bin_residual as f64) < mean_residual;
    if next_item_size >= 50 {
        if below_mean { score -= 4.5; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 10.5; } else { score += 4.5; }
    }

    // Dead-space ratio coupling — progressive quadratic ramp.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let strand_ratio = post_residual as f64 / bin_residual as f64;
        if strand_ratio > 0.55 {
            let excess = strand_ratio - 0.55;
            score += 5.8 * excess * (1.0 + 1.6 * excess)
                * (post_residual as f64 / 30.0).min(1.5);
        }
        // Awkward 12-35 band on big bins.
        if post_residual >= 12 && post_residual <= 35 && bin_residual >= 50 {
            let mid = 25.0;
            let dev = (post_residual as f64 - mid).abs();
            score += 0.45 * (1.0 - dev / 13.0).max(0.0);
        }
        // Absolute waste term for bins the next item cannot enter.
        if next_item_size > 0 && post_residual < next_item_size {
            let waste = post_residual as f64;
            score += 0.07 * waste * (1.0 - progress);
        }
        // Late-stream waste tax.
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.13 * post_residual as f64 * urgency;
        }
        // Complementarity: reward leaving post_residual ≈ mean_residual - next_item_size.
        if next_item_size > 0 && post_residual >= next_item_size {
            let target = (mean_residual - next_item_size as f64).abs();
            let closeness = (post_residual as f64 - target).abs();
            if closeness <= 6.0 {
                score -= 2.2 * (1.0 - closeness / 7.0);
            }
        }
        // NEW: penalize bins whose post_residual sits in the "unusable sliver"
        // zone — too small for typical future items, too big to ignore.
        if post_residual >= 1 && (post_residual as f64) < mean_residual * 0.35 {
            score += 1.5;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 20.0 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.5;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 28.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.5 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 14.0 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Mid-stream, large item with a thin fitting pool — a fresh bin
            // guarantees zero dead space for this item.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.2 * (1.0 - item_size as f64 / 100.0);
            }
            // NEW: if the best existing fit would still leave a large dead
            // pocket, a fresh bin is comparatively attractive.
            if post_residual as f64 > 0.5 * bin_capacity as f64 && remaining > 10.0 {
                new_bin_score -= 3.0 * (post_residual as f64 / bin_capacity.max(1) as f64);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest future item (size 1) are pure waste; the smaller the gap
    // relative to plausible item sizes, the worse the placement.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Non-linear penalty that grows sharply as residual shrinks.
        score += 60.0 / (pr + 1.0);
        // If the leftover cannot fit the lookahead item, it is likely dead
        // space: strong penalty.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // Gaps below 10 (the classic minimum size) are unusable in most
        // distributions: heavy penalty.
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 50.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * tightness;

    // Open-bin pressure: when many bins are open, prefer filling existing
    // ones rather than leaving them half-empty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.3 + progress);

    // Mean residual coupling: if average leftover is large, penalize bins
    // whose residual deviates badly (very large residual = wasted bin).
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: discourage opening a new bin unless it is truly
    // needed (few open bins or item is huge).
    if bin_residual == bin_capacity {
        let needed = open_bins_count == 0 || item_size >= 60 && fitting_bins_count == 0;
        if !needed {
            score += 30.0 + 2.0 * open_bins_count as f64;
        } else {
            score += 5.0;
        }
    }

    score
}

