pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but weight by item size so big items prefer tight fits more.
    let size_frac = item_size as f64 / bin_capacity as f64;
    score = post_residual as f64 * (1.0 + 1.5 * size_frac);

    // 2-step lookahead: perfect chain if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect 2-item completion
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // reward small leftover after the chain, penalize dead space
            score += next_post as f64 * 1.2;
            if next_post == 0 { score -= 60.0; }
        } else {
            // next item won't fit here: penalize proportionally to mismatch
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Relative to mean residual: placing into a bin with below-average residual
    // (tight bin) is good; into a loose bin wastes space.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: only open a new bin when item is large and
    // would leave a big awkward residual in every open bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline penalty; discounted when no good fit exists
        let mut penalty = 30.0;
        if post_residual <= 10 {
            penalty -= 20.0; // item nearly fills a fresh bin
        }
        if fitting_bins_count == 0 {
            penalty -= 40.0;
        }
        score += penalty;
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 3.0;

    score
}

