            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Mid-stream, large item with a thin fitting pool — a fresh bin
            // guarantees zero dead space for this item.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
            // NEW: exact-fit guarantee — a fresh bin wastes nothing for this item;
            // strengthen the pull when the best alternative would strand a large gap.
            if item_size >= 30 && remaining > 10.0 {
                new_bin_score -= 2.0 + 1.5 * item_ratio;
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 60.0 * fill_ratio * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize small dead-space leftovers that likely become unusable
    // (leftovers below the minimum plausible item size band).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // leftover is reusable by next item: strong reward, scaled by how snugly next fits
            let snug = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 45.0 * snug;
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            // leftover too small for next item: penalize proportionally
            score += 15.0 * (1.0 - post_residual as f64 / nxt);
        }
    } else {
        // Last item in stream: just minimize waste, i.e. maximize fill.
        score -= 80.0 * (item_size as f64 / residual.max(1.0));
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / residual;
        score -= 70.0 * fit_quality;
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when global state is crowded or the current fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowd = open_bins_count as f64 / (mean_residual + 1.0);
        let fit_poor = (post_residual as f64) > 40.0; // item leaves lots of waste here
        if fit_poor || (mean_residual < item_size as f64 && next_item_size as f64 > mean_residual) {
            score -= 30.0 + 20.0 * progress + 5.0 * crowd.min(10.0);
        } else {
            // discourage opening new bins when existing bins fit reasonably
            score += 50.0 - 30.0 * progress;
        }
    }

    // Global mean-residual coupling: when open bins are on average roomy,
    // prefer consolidating into bins below-average residual (compact them first).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }
    }

    // Mild time-horizon adaptation: early in the stream be more selective
    // (higher penalty for waste), later relax since fewer items remain.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

