            let mid = 25.0;
            let dev = (post_residual as f64 - mid).abs();
            score += 0.45 * (1.0 - dev / 13.0).max(0.0);
        }
        // Absolute waste term for bins the next item cannot enter.
        if next_item_size > 0 && post_residual < next_item_size {
            let waste = post_residual as f64;
            score += 0.07 * waste * (1.0 - progress);
        }
        // Late-stream waste tax.
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.13 * post_residual as f64 * urgency;
        }
        // Complementarity: reward leaving post_residual ≈ mean_residual - next_item_size.
        if next_item_size > 0 && post_residual >= next_item_size {
            let target = (mean_residual - next_item_size as f64).abs();
            let closeness = (post_residual as f64 - target).abs();
            if closeness <= 6.0 {
                score -= 2.2 * (1.0 - closeness / 7.0);
            }
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 20.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.8 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Mid-stream, large item with a thin fitting pool — a fresh bin
            // guarantees zero dead space for this item.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.4 * (1.0 - item_size as f64 / 100.0);
            }
            // NEW: fresh-bin quality gate — opening a bin for a small item mid-stream
            // is wasteful unless the fitting pool is truly poor.
            if item_size < 30 && fitting_bins_count >= 2 && mean_residual >= item_size as f64 * 1.4 {
                new_bin_score += 4.0;
            }
            // NEW: if the best existing fit would leave near-zero residual, strongly
            // prefer it over a fresh bin (zero-dead-space opportunity).
            if post_residual <= 6 && fitting_bins_count >= 1 {
                new_bin_score += 6.0;
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling: tight fits get progressively more rewarded later in stream
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 30.0 * tightness * (0.5 + progress);

    // Non-linear penalty for residual that is hard to reuse (dead space near mid-range)
    let dead = (pr / cap - 0.5).powi(2) * 4.0; // peaks at half-full residual
    score += 12.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward if next item fits the post-residual (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs() / cap;
        let fits_next = (pr >= n) as i32 as f64;
        score -= 18.0 * fits_next * (1.0 - gap).powi(3) * (0.4 + 0.6 * progress);
    }

    // Last-chance bin bonus (smooth)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 + progress);

    // Penalize opening new bins when many bins already open (encourage consolidation)
    let new_bin = (bin_residual as f64 == cap) as i32 as f64;
    score += 8.0 * new_bin * (open_bins_count as f64).sqrt() * (1.2 - progress);

    // Mild attraction to bins below mean residual (balance residuals smoothly)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - progress);

    // Small non-linear fill reward
    score -= 10.0 * fit_ratio.powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 60.0 * fill_ratio * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Penalize small dead-space leftovers that likely become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let snug = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 45.0 * snug;
            // Chain-depth probe: leftover can host multiple copies of next item.
            let depth = post_residual / next_item_size;
            if depth >= 2 {
                score -= (depth.min(4) as f64 - 1.0) * 2.5;
            }
            // Exact multi-fill bonus.
            if post_residual % next_item_size == 0 {
                let copies = post_residual / next_item_size;
                if copies >= 2 {
                    score -= 3.0 + 1.2 * copies.min(5) as f64;
                }
            }
        } else if post_residual > 0 {
            // leftover too small for next item: penalize proportionally
            let gap = (nxt - post_residual as f64);
            score += 15.0 * (1.0 - post_residual as f64 / nxt) + 0.11 * gap;
            if gap <= 4.0 {
                score -= 3.0;
            }
        }
    } else {
        // Last item in stream: just minimize waste.
        score -= 80.0 * (item_size as f64 / residual.max(1.0));
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / residual;
        score -= 70.0 * fit_quality + 0.55 * open_bins_count as f64;
    }

    // Open-bin pressure grows over the stream (consolidation incentive).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = open_bins_count as f64 * (0.55 + 0.45 * progress);
    if bin_residual != bin_capacity {
        score += pressure * 0.22;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // current fit is poor, the pool is thin, or the item is large.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation: avoid opening bins near the end.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Large item with thin fitting pool mid-stream: fresh bin avoids dead space.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    // Global mean-residual coupling: consolidate into below-average residual bins.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            if next_item_size >= 50 {
                score -= 4.5;
            } else {
                score -= 10.0;
            }
        } else {
            score += 6.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
        }

        // Dead-space ratio coupling — progressive quadratic ramp.
        if bin_residual > 0 {
            let strand_ratio = post_residual as f64 / bin_residual as f64;
            if strand_ratio > 0.55 {
                let excess = strand_ratio - 0.55;
                score += 5.5 * excess * (1.0 + 1.6 * excess)
                    * (post_residual as f64 / 30.0).min(1.5);
            }
            // Awkward 12-35 band on big bins.
            if post_residual >= 12 && post_residual <= 35 && bin_residual >= 50 {
                let dev = (post_residual as f64 - 25.0).abs();
                score += 0.45 * (1.0 - dev / 13.0).max(0.0);
            }
            // Absolute waste term for bins the next item cannot enter.
            if next_item_size > 0 && post_residual < next_item_size {
                score += 0.06 * post_residual as f64 * (1.0 - progress);
            }
            // Late-stream waste tax.
            let remaining_items = (total_items - step_index) as f64;
            if remaining_items < 15.0 && post_residual > 0 {
                let urgency = (15.0 - remaining_items) / 15.0;
                score += 0.12 * post_residual as f64 * urgency;
            }
            // Complementarity: reward leaving post_residual ≈ mean_residual - next_item_size.
            if next_item_size > 0 && post_residual >= next_item_size {
                let target = (mean_residual - next_item_size as f64).abs();
                let closeness = (post_residual as f64 - target).abs();
                if closeness <= 6.0 {
                    score -= 2.0 * (1.0 - closeness / 7.0);
                }
            }
        }
    }

    // Mild time-horizon adaptation.
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Reward (subtract) placements whose leftover lands in "usable" harmonic classes.
    // Classes: <=0.1 (near-perfect), (0.1,0.3] (fills with small items), (0.3,0.5],
    // (0.5,0.7], (0.7,0.9], (0.9,1.0) (nearly empty -> wasteful split).
    let class: f64 = if post == 0.0 {
        -12.0 // perfect fit, huge reward
    } else if frac <= 0.1 {
        -8.0
    } else if frac <= 0.3 {
        -4.0
    } else if frac <= 0.5 {
        -1.0
    } else if frac <= 0.7 {
        1.0
    } else if frac <= 0.9 {
        3.0
    } else {
        6.0 // bin left almost full but item was small: poor packing
    };
    score += class;

    // Integer-division threshold coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead chainable: subtract proportional to how snugly next fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 3.0 + 2.0 * (1.0 - snug / cap);
        } else {
            // next item cannot chain here: penalize proportionally to wasted potential
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Penalize spreading across many open bins when mean residual is already low.
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64).ln();
    }

    // Early stream: prefer tighter fills; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * frac * 2.0;

    // Mean-residual coupling: if this bin's residual is far below mean, it's already
    // a "harmonically low" bin; placing here keeps big residuals for big items.
    score += 0.5 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance bands, retuned.
    if post_residual < 10 {
        score += 70.0;
    } else if post_residual < 20 {
        score += 33.0;
    } else if post_residual < 30 {
        score += 11.0;
    } else if post_residual < 45 {
        score += 1.5;
    }

    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 92.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 8 {
        score -= 13.5;
    }

    // Tightness reward, amplified for large items; quadratic flavor retained.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let tight_w = if item_size >= 50 { 35.0 } else { 21.5 };
    score -= tight_w * tightness + 6.5 * tightness * tightness;

    // Open-bin pressure grows over the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.55 + 0.45 * progress);
    score += pressure * 0.35;

    // Last-chance bin: only bin that fits — using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.55 * open_bins_count as f64;
    }

    // Lookahead: exact or near-exact chain fits are strongly favored.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        let chain_bonus = if next_tight == 0.0 {
            38.0
        } else if next_tight <= 10.0 {
            26.0 * (1.0 - next_tight / 110.0)
        } else {
            15.0 * (1.0 - next_tight / 100.0)
        };
        score -= chain_bonus;
        if next_tight > 0.0 && next_tight <= 25.0 && next_item_size >= 30 {
            score -= 3.5;
        }
        if next_item_size >= 60 && next_tight <= 15.0 {
            score -= 7.0;
        }
        // Two-step chain awareness.
        if post_residual >= next_item_size * 2 {
            let two_step = post_residual - next_item_size * 2;
            if two_step <= 12 {
                score -= 4.0 * (1.0 - two_step as f64 / 14.0);
            }
        }
        // Three-step chain probe for small items.
        if next_item_size <= 25 && post_residual >= next_item_size * 3 {
            let three_step = post_residual - next_item_size * 3;
            if three_step <= 6 {
                score -= 3.0 * (1.0 - three_step as f64 / 8.0);
            }
        }
        // Continuous chain-depth probe, extended to depth 5 for very small
        // next items — deep stacking on mid residuals reduces bin count.
        if next_item_size > 0 {
            let depth = post_residual / next_item_size;
            if depth >= 2 {
                let cap = if next_item_size <= 15 { 5.0 } else { 4.0 };
                score -= (depth.min(cap as u32) as f64 - 1.0) * 2.2;
            }
        }
        // Exact multi-fill: post_residual is an exact multiple of the next item.
        if post_residual % next_item_size == 0 {
            let copies = post_residual / next_item_size;
            if copies >= 2 {
                score -= 3.0 + 1.2 * copies.min(5) as f64;
            }
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item; scale penalty with gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 10.0 + 0.11 * gap;
        if gap <= 4.0 {
            score -= 3.0;
        }
        if post_residual <= 3 {
            score += 2.0;
        } else if gap > 12.0 {
            score += 0.08 * gap;
        }
        // If the stranded residual could still host a later item of
        // typical size, soften the penalty — the sliver isn't necessarily dead.
        let typical = mean_residual.max(1.0);
        if post_residual as f64 >= typical * 0.9 {
            score -= 2.5;
        }
    }

    // Mean-residual coupling with variance awareness.
    let below_mean = (bin_residual as f64) < mean_residual;
    if next_item_size >= 50 {
        if below_mean { score -= 4.5; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 10.0; } else { score += 4.5; }
    }

    // Dead-space ratio coupling — progressive quadratic ramp.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let strand_ratio = post_residual as f64 / bin_residual as f64;
        if strand_ratio > 0.55 {
            let excess = strand_ratio - 0.55;
            score += 5.5 * excess * (1.0 + 1.6 * excess)
                * (post_residual as f64 / 30.0).min(1.5);
        }
        // Awkward 15-35 band on big bins.
        if post_residual >= 12 && post_residual <= 35 && bin_residual >= 50 {
            let mid = 25.0;
            let dev = (post_residual as f64 - mid).abs();
            score += 0.45 * (1.0 - dev / 13.0).max(0.0);
        }
        // Absolute waste term — progressive tax scaled by next-item fit odds.
        if next_item_size > 0 && post_residual < next_item_size {
            let waste = post_residual as f64;
            score += 0.06 * waste * (1.0 - progress);
        }
        // Late-stream waste tax — residual left behind is almost certainly
        // final waste when few items remain.
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.12 * post_residual as f64 * urgency;
        }
        // Complementarity: reward post_residual close to (mean_residual -
        // next_item_size), steering residuals toward a fillable target zone.
        if next_item_size > 0 && post_residual >= next_item_size {
            let target = (mean_residual - next_item_size as f64).abs();
            let closeness = (post_residual as f64 - target).abs();
            if closeness <= 6.0 {
                score -= 2.0 * (1.0 - closeness / 7.0);
            }
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation — a fresh bin is cheap only if the
            // remaining stream can fill it.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            // Mid-stream dump risk.
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Mid-stream, large item with a thin fitting pool — a fresh bin
            // guarantees zero dead space for this item.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    }
    // Medium gaps (10..=19) can still fit small items, mild penalty.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 15.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize gaps that cannot fit the next item at all (dead space w.r.t. future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But if no open bin fits at all, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference for tighter bins overall (deviation from mean residual).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight tightening pressure as the stream progresses (waste less early).
    let progress = step_index as f64 / total_items as f64;
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
