    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain fit: strongly reward.
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover as hard as possible.
        score += 20.0;
    }

    // Tight fits are valuable: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize bins whose residual deviates badly from mean (avoid fragmenting many bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (i.e., post_residual of this empty bin is large and item is large).
