        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + 0.5 * waste;
        // If the item is huge and next item is huge too, opening fresh may be wise.
        if item_size > bin_capacity / 2 && next_item_size > bin_capacity / 2 {
            score -= 45.0;
        }
    }

    // Early in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);

    score
}

