pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual)
    let mut score = post;

    // Smooth non-linear coupling: waste penalty grows super-linearly with
    // normalized residual, modulated by stream progress.
    let waste = pr * pr * (1.0 + 3.0 * progress);
    score += waste * cap;

    // Interaction of post residual with mean residual: penalize bins whose
    // leftover deviates above the fleet mean (dead-space hoarding).
    let dev = (mean_residual - post) / cap;
    score += 20.0 * dev * dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead coupling: reward leaving a gap that fits the next item,
    // penalize residual just below the next item size (smooth bump).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post) / cap;
        let bump = (-gap * gap * 400.0).exp(); // ~1 when post == next size
        score -= 25.0 * bump;
        // penalize leaving residual slightly too small for next item
        let tight = ((-gap / 0.05).exp() + 1.0).ln();
        score += 15.0 * tight * pr;
    }

    // New-bin candidate: prefer keeping bins open early, allow opening
    // new bins late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score = cap * (0.6 + 0.5 * progress) - 20.0 * fragmentation * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += 2.0 * (open_bins_count as f64).ln() * pr;

    score
}

