            }
        }
        // NEW: penalize filling bins that still have large residual when
        // small items remain — keep wide bins for awkward future items.
        if item_size <= 20 && bin_residual >= 70 && next_item_size >= 45 {
            score += 2.5;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
