pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: tighter fit preferred (small post_residual already favored).

    // Harmonic class of the residual gap after placement.
    // Residuals divisible by large chunk sizes are "harmonic" — likely to be
    // reusable by future items; penalize odd/tiny gaps.
    let gap = post_residual;
    if gap == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else {
        // Modulo-based class rewards: gap % k == 0 means a k-sized item slots in.
        let mut harmony = 0.0;
        if gap % 10 == 0 { harmony += 6.0; }
        if gap % 20 == 0 { harmony += 4.0; }
        if gap % 25 == 0 { harmony += 4.0; }
        if gap % 50 == 0 { harmony += 5.0; }
        score -= harmony;

        // Dead-space penalty for tiny unusable gaps (1..5) unless gap == 0.
        if gap < 5 {
            score += 40.0;
        } else if gap < 10 {
            score += 15.0;
        }

        // Integer-division thresholds: classify gap into tiers.
        let tier = gap / 10; // 0..10
        // Mid-tier gaps (30..70) are the most reusable; slight reward.
        if tier >= 3 && tier <= 7 {
            score -= 3.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == gap {
            score -= 120.0;
        } else if next_item_size <= gap {
            // Next item fits but leaves another gap: mild reward scaled by fit tightness.
            let n_gap = gap - next_item_size;
            score -= 20.0 - (n_gap as f64) * 0.2;
            // Harmonic bonus if resulting gap again lands on a class boundary.
            if n_gap % 10 == 0 { score -= 5.0; }
        } else {
            // Next item cannot use this bin's remainder: penalize slightly,
            // unless the gap is harmonically reusable anyway.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual.
    // Penalize opening a new bin unless current open bins are all badly filled.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // If few bins fit the item, opening fresh is more attractive.
        if fitting_bins_count == 0 {
            score -= 500.0;
        } else if fitting_bins_count == 1 {
            score += 40.0; // last-chance existing bin should win instead
        }
        // As stream progresses, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If mean residual across open bins is large, avoid new bins.
        if mean_residual > item_size as f64 {
            score += 25.0;
        }
        // With many open bins, discourage more.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // Existing bin: mild preference as open bin count grows (fill them).
        score -= (open_bins_count as f64) * 0.5;
    }

    // Slight nudge toward fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

