        if below_mean { score -= 4.5; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 10.0; } else { score += 4.5; }
    }

    // Dead-space ratio coupling.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let strand_ratio = post_residual as f64 / bin_residual as f64;
        if strand_ratio > 0.55 {
            let excess = strand_ratio - 0.55;
            score += 5.5 * excess * (1.0 + 1.6 * excess)
                * (post_residual as f64 / 30.0).min(1.5);
        }
        if post_residual >= 12 && post_residual <= 35 && bin_residual >= 50 {
            let dev = (post_residual as f64 - 25.0).abs();
            score += 0.45 * (1.0 - dev / 13.0).max(0.0);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.06 * post_residual as f64 * (1.0 - progress);
        }
        // Late-stream waste tax.
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.12 * post_residual as f64 * urgency;
        }
        // Complementarity with mean residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            let target = (mean_residual - next_item_size as f64).abs();
            let closeness = (post_residual as f64 - target).abs();
            if closeness <= 6.0 {
                score -= 2.0 * (1.0 - closeness / 7.0);
            }
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            // Late-stream consolidation.
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    // Mild early-stream selectivity (softened from parent).
    score *= 1.0 + 0.08 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum plausible
    // future item size (1..=100 interface, but small gaps are hard to fill)
    // are heavily penalized. Penalize gaps in [1, 12] super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - pr) * (13.0 - pr) * 2.5;
    }
    // Also penalize the awkward mid-range gap [13, 25] mildly.
    else if post_residual > 12 && post_residual <= 25 {
        score += (25.0 - pr) * 1.2;
    }

    // Reward tight fits (small waste) with a bonus.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Perfect or near-perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; when few bins are open,
    // be pickier about fits.
    let ob = open_bins_count as f64;
    score += ob * 2.0;

    // Coupling with mean residual: if this bin's post-fit residual is far
    // below the mean residual, it's a good consolidation target.
    let bin_res = bin_residual as f64;
    if bin_res < mean_residual {
        score -= (mean_residual - bin_res) * 0.6;
    } else {
        score += (bin_res - mean_residual) * 0.3;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward keeping this bin alive with that shape of gap.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr).abs() <= 1.0 {
            score -= 80.0;
        } else if n < pr && pr - n <= 12.0 {
            score -= 25.0;
        } else if n > pr {
            // Next item won't fit here; slightly prefer a tighter current fit.
            score += (n - pr) * 0.4;
        }
    }

    // New-bin candidate: an empty bin has large residual; make it moderately
    // attractive only when current fits are bad (large post_residual) and
    // stream is early. Late in the stream, discourage opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let badness = (pr - 12.0).max(0.0);
        score = 100.0 - badness * 1.5 - (1.0 - progress) * 20.0 + ob * 3.0;
        // If the next item is large, an empty bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

