    let mut score = post_residual as f64;

    // Core best-fit: prefer smallest post residual.
    // Tight fit bonus (post_residual near 0 is excellent).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this bin is a perfect two-item chain — strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item can still fit here; residual remains useful.
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit in this residual: dead space penalty grows
            // with how wasted the residual is relative to next item.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should be penalized when any open
    // bin gives a reasonable fit; only attractive when fits are bad or rare.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so open bins are preferred by default.
        score += 25.0;
        // More open bins => more penalty for opening another.
        score += open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is wasteful.
        score += progress * 20.0;
        // If mean residual across open bins is large, open bins are roomy;
        // opening a new bin is even less attractive.
        score += mean_residual * 0.5;
        // If no open bin fits (fitting_bins_count counts only open bins that
        // can fit; a new bin always "fits"), soften the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            // Last-chance open bin already gets a bonus; keep new bin unattractive.
            score += 10.0;
        }
    }

    // Global state: when many bins are open with high mean residual,
    // slightly prefer consolidating into bins with large residuals (fill roomy bins).
    if bin_residual < bin_capacity {
        let roominess = bin_residual as f64 / bin_capacity as f64;
        score += roominess * 5.0;
        // Prefer bins whose residual is above average (they can absorb more later).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Time-horizon modulation: early in the stream, be conservative with open
    // bins (keep flexibility); late, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64) * 0.1;

    score
}

