            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near multiples of common
    // item sizes are more likely to be fillable later.
    let cap = bin_capacity as f64;

    // Fraction of capacity consumed by this placement
    let fill_frac = item_size as f64 / cap;
    score -= 6.0 * fill_frac;

    // Harmonic classes: post_residual divisible by small sizes (5,10,20,25)
    // leaves reusable chunks; penalize residues that are "odd" classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else {
        let mut bonus = 0.0;
        if pr % 5 == 0 { bonus += 2.0; }
        if pr % 10 == 0 { bonus += 3.0; }
        if pr % 20 == 0 { bonus += 2.0; }
        if pr % 25 == 0 { bonus += 2.0; }
        if pr % 50 == 0 { bonus += 3.0; }
        // small leftover in a fine harmonic class is good
        if pr <= 10 && pr % 5 == 0 { bonus += 4.0; }
        score -= bonus;

        // penalize "awkward" residues: coprime-ish to common sizes
        if pr % 5 != 0 && pr % 10 != 0 && pr % 20 != 0 && pr % 25 != 0 {
            score += 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it doesn't fit, mildly penalize tight bins.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let nclass = next_item_size % 10;
            if pr % 10 == nclass { score -= 5.0; }
            score -= 3.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad fit
    // unless the fit is tight (small post_residual).
    if fitting_bins_count == 1 {
        if post_residual > 40 {
            score += 15.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate: empty bin. Prefer it when open bins are fragmented
    // or when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap - item_size as f64; // baseline: residual after placement
        // penalize opening new bins early in the stream or when many bins open
        score += 8.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        score += 2.0 * open_bins_count as f64;
        // but reward opening a fresh bin when existing ones are fragmented
        score -= 10.0 * frag;
        // large items pack cleanly into fresh bins
        score -= 4.0 * fill_frac;
    }

    // Progress-aware tightening: later in stream, be greedier about closure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

