    // Mean-residual coupling.
    let below_mean = (bin_residual as f64) < mean_residual;
    if next_item_size >= 50 {
        if below_mean { score -= 4.5; } else { score -= 2.0; }
    } else {
        if below_mean { score -= 10.0; } else { score += 4.5; }
    }

    // Dead-space ratio coupling — progressive quadratic ramp.
    if bin_residual > 0 && bin_residual != bin_capacity {
        let strand_ratio = post_residual as f64 / bin_residual as f64;
        if strand_ratio > 0.55 {
            let excess = strand_ratio - 0.55;
            score += 5.5 * excess * (1.0 + 1.6 * excess)
                * (post_residual as f64 / 30.0).min(1.5);
        }
        // Awkward 15-35 band on big bins.
        if post_residual >= 12 && post_residual <= 35 && bin_residual >= 50 {
            let dev = (post_residual as f64 - 25.0).abs();
            score += 0.45 * (1.0 - dev / 13.0).max(0.0);
        }
        // Waste tax when next item cannot use the leftover.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.06 * post_residual as f64 * (1.0 - progress);
        }
        // Late-stream waste tax.
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.12 * post_residual as f64 * urgency;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            // Large item with a poor pool: a fresh bin keeps big items from
            // stranding mid residuals; scaled by stream length.
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: fraction of residual consumed by this item
    let residual = bin_residual as f64;
    let fit_ratio = if residual > 0.0 { item_size as f64 / residual } else { 0.0 };

    // Reward tight fits (low post_residual relative to residual): subtract proportionally
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving large dead space relative to typical item sizes
    if post_residual > 0 && post_residual < 10 {
        // small unusable sliver is fine — item nearly fills bin; strong reward
        score -= 15.0;
    } else if post_residual >= 10 && post_residual < item_size {
        // leftover that can still hold small items: moderate penalty
        score += (post_residual as f64) * 0.25;
    } else if post_residual >= item_size && post_residual < 20 {
        // leftover big enough for another item of same class: reward
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 {
        let next_fits = (next_item_size as u32) <= post_residual;
        if next_fits {
            let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 20.0 * (1.0 - exact / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for blocking good future use
            score += 6.0;
        }
        // If next item is huge, prefer conserving bins with large residuals
        if next_item_size > 60 && post_residual < next_item_size && post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: tighten selection pressure
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score -= 5.0 * (mean_gap / bin_capacity as f64);
    } else {
        score += 3.0 * (-mean_gap / bin_capacity as f64);
    }

    // Time horizon: early in stream, opening bins is cheap (favor new bins when fit is bad);
    // late in stream, squeeze everything into existing bins
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += progress * 10.0 * open_pressure * 0.1;
    score -= (1.0 - progress) * 3.0 * open_pressure * 0.1;

    // New-bin candidate handling: only attractive when the item fits poorly everywhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 45.0;
        // But if this is a perfect fit (item == capacity) it's ideal
        if item_size == bin_capacity {
            score -= 100.0;
        }
        // If few fitting bins and the fit elsewhere is loose, new bin becomes viable
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // Early stream: new bins cheaper to open
        score -= 20.0 * (1.0 - progress);
        // Large item with poor expected fit: opening fresh bin avoids fragmentation
        if item_size > 70 {
            score -= 12.0;
        }
    }

    // Exact-fill celebration
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

