pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 / mod 25.
    let r = post_residual;
    let mod10 = r % 10;
    let mod25 = r % 25;

    // Penalize residuals that are "off-harmonic" (not multiples of common item granularities).
    if r == 0 {
        score -= 40.0; // perfect fit is best
    } else {
        score += (mod10 as f64) * 0.8;
        score += (mod25 as f64) * 0.6;
        // Harmonic sweet spots: residuals divisible by 10 or 25 are more reusable.
        if mod10 == 0 { score -= 6.0; }
        if mod25 == 0 { score -= 8.0; }
        if r % 50 == 0 { score -= 5.0; }
    }

    // Small dead space (< 10, unusable for any item) is heavily penalized.
    if r > 0 && r < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.4;
            // Harmonic match: next item leaves a multiple-of-10 residue again.
            if (r - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            // Next item won't fit here; penalize proportionally to overflow.
            score += (next_item_size - r).min(20) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (fresh empty bin): default is mildly unattractive,
    // but attractive if no open bin is a good harmonic fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // prefer using the single fitting bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += mean_residual * 0.05;
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

