pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    }

    // Reward leaving gaps that can still fit small future items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Progress-based tightening: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 1.2;

    // Prefer bins tighter than the mean residual (consolidate waste).
    score += (mean_residual - bin_residual as f64) * 0.3;

