pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: does the next item fit the leftover?
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            // leftover is reusable by the next item: strong reward
            let tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 120.0 * tight;
        } else if post_residual < next_item_size && post_residual > 0 {
            // dead space relative to the next item: penalize proportionally
            let waste = (post_residual as f64) / (next_item_size.max(1) as f64);
            score += 60.0 * waste;
        }
        // leftover exactly matches next item: perfect chain
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // last item: prefer filling a bin as tightly as possible
        score -= 150.0;
    }

    // Relative-to-mean coupling: bins below mean residual are more "spent",
    // favor finishing them rather than leaving scattered small residuals
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && open_bins_count.iter().count() > 0
            && (bin_residual as f64 - item_size as f64) > (mean_residual - item_size as f64);
        // base cost of opening a new bin
        score += 400.0;
        if good_fit_exists {
            score += 200.0; // discourage opening when open bins can take it
        }
