    // Smooth non-linear coupling of post_residual with stream progress:
    // as the stream progresses, increasingly punish large leftover residual
    // (dead space), while early on residual is less costly.
    score += 40.0 * progress * x * x * (1.0 - x);

    // Reward tight fits: smooth interaction between fill fraction and progress
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates badly from the mean residual
    score += 0.15 * (post - mean_residual).abs();

