    score += 0.5 * (open_bins_count as f64) * progress;

    // New-bin candidate handling: neutral baseline so it's chosen only when
    // all open bins score poorly (their dead-space penalties accumulate).
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 0.1 * (post - mean_residual);
    }

    score
}

