    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual: which "slot" of capacity does the leftover occupy ----
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12
    let post = post_residual as f64;

    // Harmonic class index: floor(post_residual / (C/8)) -> 0..8 classes
    let post_class = (post_residual / eighth) as f64;
    // Penalize odd harmonic classes (mid-band dead space is hardest to reuse)
    if post_residual % eighth != 0 {
        score += 2.0;
    }
    // Class-based nonlinear penalty: dead space near C/2 (class 4) is worst
    let class_penalty = ((post_class - 4.0).abs() * 1.5).powi(2) * 0.25;
    score += class_penalty;

    // ---- Exact quarter-fraction fits are golden (harmonic resonance) ----
    if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // ---- Lookahead: does next item harmonically divide the post residual? ----
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits exactly -> strong reward
        if next_item_size == post_residual {
            score -= 10.0;
        } else {
            // modular harmony: next_item divides post_residual evenly
            if post_residual % next_item_size == 0 {
                score -= 5.0;
            } else {
                score -= 2.0;
            }
        }
    } else if next_item_size > 0 {
        // next item cannot use this leftover: penalize proportional to wasted potential
        score += (next_item_size as f64 - post).min(30.0) * 0.3;
    }

    // ---- Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if all open bins would leave bad harmonic classes
        let mean_class = mean_residual / (quarter as f64);
        // If mean residual is in a good reusable band (> quarter), prefer existing bins
        if mean_residual > quarter as f64 {
            score += 15.0;
        } else {
            score += 4.0;
        }
        // Late in stream, opening new bins is fine (many items left to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 3.0;
        // If item is large (> 3/4 capacity), new bin is natural
        if item_size * 4 > bin_capacity * 3 {
            score -= 10.0;
        }
        let _ = mean_class;
    }

    // ---- Integer-division threshold on post_residual: tiny leftovers are toxic ----
    if post_residual > 0 && post_residual < eighth {
        score += 5.0;
    }
    // Leftover exactly divisible into quarters is reusable
    if post_residual > 0 && post_residual % quarter == 0 {
        score -= 3.0;
    }

    // Mild tie-break: prefer fuller bins (lower residual before placement)
    score += (bin_residual as f64) * 0.01;

    score
}

