            // residual that still fits the next item comfortably.
            if next_item_size > 0 && post_residual >= next_item_size {
                new_bin_score += 2.0;
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if no plausible future item (min size 1..small) can use it well.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny gap: pure dead space, strong penalty.
            score += 40.0 + 6.0 * (10.0 - pr);
        } else if post_residual < 25 {
            // Small gap: only usable by very small items; moderate penalty.
            score += 12.0 + 0.8 * (25.0 - pr);
        } else if post_residual <= 60 {
            // Mid gap: mildly discouraged relative to tight fits.
            score += 0.3 * (60.0 - pr);
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement creates a perfect chain — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves another gap; scale by how tight.
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 - 0.15 * slack;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += 0.2 * (next_item_size as f64 - pr).min(30.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // offers a decent fit. Give the empty bin a baseline cost plus pressure from
    // the number of already-open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening fresh is fine.
        let fit_tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fit_tightness;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // residual mass (drive toward fewer bins).
    score += 0.05 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // Slight preference for bins whose residual is below the mean (tighter bins
    // get filled first, keeping loose bins flexible).
    let res = bin_residual as f64;
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        score += 0.15 * (res - mean_residual);
    }

    // Progress term: late in the stream, be more aggressive about closing bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * pr / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.55 + 0.45 * progress);

    // Dead-space avoidance bands — sharpen the low bands where stranded
    // capacity becomes permanent waste.
    if post_residual < 10 {
        score += 72.0;
    } else if post_residual < 20 {
        score += 34.0;
    } else if post_residual < 30 {
        score += 11.0;
    } else if post_residual < 45 {
        score += 1.5;
    }

    // Perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 94.0;
    } else if post_residual <= 5 {
        score -= 36.0;
    } else if post_residual <= 8 {
        score -= 13.5;
    }

    // Tightness reward, amplified for large items; quadratic flavor.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    let tight_w = if item_size >= 50 { 35.0 } else { 21.5 };
    score -= tight_w * tightness + 6.5 * tightness * tightness;

    // Open-bin pressure grows over the stream.
    score += pressure * 0.35;

    // Last-chance bin: only bin that fits — using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.55 * open_bins_count as f64;
    }

    // Lookahead chain fits — combined with fine residual grading.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        let chain_bonus = if next_tight == 0.0 {
            40.0
        } else if next_tight <= 10.0 {
            27.0 * (1.0 - next_tight / 110.0)
        } else {
            15.0 * (1.0 - next_tight / 100.0)
        };
        score -= chain_bonus;
        if next_tight > 0.0 && next_tight <= 25.0 && next_item_size >= 30 {
            score -= 3.5;
        }
        if next_item_size >= 60 && next_tight <= 15.0 {
            score -= 7.0;
        }
        // Two-step chain awareness.
        if post_residual >= next_item_size * 2 {
            let two_step = post_residual - next_item_size * 2;
            if two_step <= 12 {
                score -= 4.0 * (1.0 - two_step as f64 / 14.0);
            }
        }
        // Three-step chain probe for small items.
        if next_item_size <= 25 && post_residual >= next_item_size * 3 {
            let three_step = post_residual - next_item_size * 3;
            if three_step <= 6 {
                score -= 3.0 * (1.0 - three_step as f64 / 8.0);
            }
        }
        // Continuous chain-depth probe.
        let depth = post_residual / next_item_size;
        if depth >= 2 {
            let cap = if next_item_size <= 15 { 5.0 } else { 4.0 };
            score -= (depth.min(cap as u32) as f64 - 1.0) * 2.2;
        }
        // Exact multi-fill — residual divides evenly by next item.
        if post_residual % next_item_size == 0 {
            let copies = post_residual / next_item_size;
            if copies >= 2 {
                score -= 3.0 + 1.2 * copies.min(5) as f64;
            }
        }
        // Complementarity with the residual pool.
        let target = (mean_residual - next_item_size as f64).abs();
        let closeness = (post_residual as f64 - target).abs();
        if closeness <= 6.0 {
            score -= 2.0 * (1.0 - closeness / 7.0);
        }
        // NEW: residual-grading lookahead — if post_residual leaves a
        // remainder that lands in the "valuable small residual" zone
        // (<= 8), the next item placement is nearly perfect twice over.
        let rem = post_residual - next_item_size;
        if rem <= 8 && rem > 0 {
            score -= 2.0 * (1.0 - rem as f64 / 9.0);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        let gap = (next_item_size - post_residual) as f64;
