    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / (bin_capacity as f64).max(1.0);
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
