            let chain = (post_residual - next_item_size) as f64;
            score -= (1.5 - t) * (2.0 + 8.0 / (1.0 + chain));
        } else {
            // dead space penalty scaled by how badly next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += (0.5 + t) * (miss * miss) / 100.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * t;
    }

    // Penalize bins with many fitting alternatives slightly (keep choice diversity)
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: when many bins are open, tighten packing discipline
    let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(4.0);
    score += 0.5 * open_pressure;

    // Prefer bins whose residual deviates below the mean (consume stragglers)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when item is large relative to mean residual
    if bin_residual == bin_capacity {
