pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_mod10 = (post_residual % 10) as f64;
    let post_mod25 = (post_residual % 25) as f64;
    let post_quot = (post_residual / 25) as f64; // integer division threshold class

    // Reward post-residuals that lie in "harmonic" classes (small, near-zero modulo),
    // i.e. residues that are likely to be filled by typical item sizes.
    let residue_penalty = (post_mod10 / 10.0) * 8.0 + (post_mod25 / 25.0) * 6.0;
    score += residue_penalty;

    // Integer-division thresholds: post-residual in [0,10) is nearly dead space; penalize
    // classes [10,25) and [25,50) differently since larger leftovers remain usable.
    if post_residual < 10 {
        score += 6.0; // dead space class
    } else if post_residual < 25 {
        score -= 2.0;
    } else if post_residual < 50 {
        score -= 4.0;
    } else {
        score -= 5.0 * post_quot / 4.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Exact modulo match: next item perfectly fills the leftover.
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            } else {
                let leftover2 = post_residual - next_item_size;
                // Harmonic class of the second-order residual.
                let l2 = (leftover2 % 10) as f64;
                score -= 5.0 - (l2 / 10.0) * 4.0;
                score += leftover2 as f64 * 0.05;
            }
        } else {
            // Next item won't fit here; slight penalty scaled by overflow fraction.
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow / cap) * 12.0;
        }
    } else {
        // Last item: strongly prefer minimal post-residual.
        score += post * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: neutral baseline slightly above well-fitting open bins,
    // but attractive when existing residuals are large/fragmented.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.15 + (open_bins_count as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big next item: fresh bin is fine
        }
    }

    // Progress-aware tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.1 * progress;

    // Coupling with mean residual: prefer bins below the mean residual (tighter fit).
    score += (mean_residual - post) * 0.08;

    score
}

