}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: small post_residual that is still too large for typical items.
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that blocks the next item.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap > 0.0 && (gap as u32) < next_item_size {
            score += 0.6 * (next_item_size - gap as u32) as f64;
        } else if next_item_size as f64 <= gap {
            // Reward leaving space usable by the next item.
            score -= 0.3 * (gap - next_item_size as f64).min(30.0);
        }
        // If next item exactly fits post_residual, big reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive when the item fits
    // poorly everywhere else (large item, few fitting bins, fragmented residuals).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // New bin gets a base cost so it's only chosen when clearly better.
        let mut new_bin_score = bin_capacity as f64 * 0.55 + 20.0;
        // Late in the stream or heavily fragmented open bins -> new bin more attractive.
        new_bin_score -= 25.0 * progress;
        new_bin_score -= 20.0 * fragmentation;
        // Large items are hard to place later; reserve fresh space for them.
        new_bin_score -= 0.15 * item_size as f64;
        // If many bins can already fit the item, opening a new bin is wasteful.
        new_bin_score += 6.0 * fitting_bins_count as f64;
        // Lookahead: a fresh bin can host both item and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 18.0;
        }
        score = score.min(new_bin_score) * 0.0 + score; // keep open-bin score
        return if new_bin_score < score { new_bin_score } else { score };
    }

    // Mild penalty for spreading load across many bins when residuals are large.
    if post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

