        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.06 * post_residual as f64 * (1.0 - progress);
        }
        let remaining_items = (total_items - step_index) as f64;
        if remaining_items < 15.0 && post_residual > 0 {
            let urgency = (15.0 - remaining_items) / 15.0;
            score += 0.12 * post_residual as f64 * urgency;
        }
        // Variance-aware dead-space penalty. When residuals are tightly
        // clustered (low spread), a large leftover is more likely to be
        // permanently wasted, so penalize it more aggressively.
        let spread = (bin_residual as f64 - mean_residual).abs();
        let tight_pool = (1.0 - (spread / 40.0).min(1.0)).max(0.0);
        if post_residual > 20 {
            score += 0.09 * (post_residual - 20) as f64 * tight_pool
                * (1.0 - progress * 0.5);
        }
        // NEW: stranded-waste estimator. Estimate the probability that the
        // post residual can never be filled by future items, based on how
        // far it sits below the mean residual. Penalize proportionally to
        // the wasted capacity it represents.
        if post_residual > 0 {
            let mr = mean_residual.max(1.0);
            let fill_prob = ((post_residual as f64) / mr).min(1.2);
            let strand_risk = (1.0 - fill_prob).max(0.0);
            if strand_risk > 0.0 {
                score += 1.8 * strand_risk * strand_risk
                    * (post_residual as f64 / 25.0).min(2.0)
                    * (0.6 + 0.4 * progress);
            }
        }
        // NEW: smooth quadratic dead-space gradient between the discrete
        // bands, rewarding leaving residuals near the small-item scale
        // (1..=10) which are easiest to close out later.
        let small_scale = 10.0;
        if post_residual as f64 > small_scale && post_residual <= 30 {
            let over = post_residual as f64 - small_scale;
            score += 0.35 * over * over / 40.0;
        }
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut new_bin_score = 6.0 + pressure * 0.18;
        if item_size >= 60 {
            new_bin_score -= 19.5 + 11.0 * item_ratio;
        } else if item_size >= 40 {
            new_bin_score -= 6.0;
        } else {
            new_bin_score += 13.5;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 27.0;
        } else {
            let poor_pool = mean_residual < (item_size as f64) * 1.15;
            if poor_pool {
                new_bin_score -= 6.0 * item_ratio;
            } else {
                new_bin_score += 2.0 * item_ratio;
            }
            if fitting_bins_count == 1 && post_residual < 14 {
                new_bin_score -= 13.5 - 0.35 * post_residual as f64;
            }
            if post_residual as f64 > 0.45 * bin_residual as f64 {
                new_bin_score -= 4.5 * item_ratio;
            }
            if next_item_size >= 55 && mean_residual < next_item_size as f64 * 0.8 {
                new_bin_score -= 3.5;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                new_bin_score -= 2.5 + 0.05 * next_item_size as f64;
            }
            if open_bins_count > 8 && mean_residual < 20.0 {
                new_bin_score -= 1.5 + 0.1 * (open_bins_count as f64 - 8.0).min(10.0);
            }
            let remaining = (total_items - step_index) as f64;
            if remaining < 8.0 {
                new_bin_score += 2.0 * (8.0 - remaining);
            }
            if next_item_size > 0 && post_residual < next_item_size && remaining > 20.0 {
                new_bin_score += 1.5;
            }
            if item_size >= 55 && mean_residual < item_size as f64 * 1.3 && remaining > 15.0 {
                new_bin_score -= 4.0 * (1.0 - item_size as f64 / 100.0);
            }
            // If the chosen bin would leave a residual that no typical
            // future item can fill, opening fresh is preferable.
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let gap = (next_item_size - post_residual) as f64;
                if gap > mean_residual.max(1.0) {
                    new_bin_score -= 2.5 * (gap / 30.0).min(1.5);
                }
            }
            // NEW: when the best achievable post residual among open bins is
            // still far above the mean residual mid-stream, a fresh bin
            // preserves a more usable residual distribution.
            if post_residual as f64 > mean_residual.max(1.0) * 1.6 && remaining > 25.0 {
                new_bin_score -= 2.0 * ((post_residual as f64 - mean_residual) / 20.0).min(1.5);
            }
        }
        if progress < 0.3 {
            new_bin_score -= 6.5 * (0.3 - progress) / 0.3;
        }
        if progress > 0.8 {
            new_bin_score += 5.0 * (progress - 0.8) / 0.2;
        }
        if progress >= 0.3 && progress <= 0.8 && item_size < 40 {
            new_bin_score += 2.0;
        }
        score += new_bin_score;
    }

    score
}

