pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into modulo-10 bands.
    let pr = post_residual as i64;
    let band = pr % 10;
    // Penalize leftovers in "hard to fill" bands (7,8,9 are prime-ish dead space for 10..80 items;
    // small bands 1,2,3 are also near-useless). Favor bands 0,4,5,6.
    let band_penalty: f64 = match band {
        0 => -6.0,
        4 | 5 | 6 => -3.0,
        1 | 2 | 3 => 2.0,
        _ => 4.0, // 7,8,9
    };
    score += band_penalty;

    // Integer-division threshold: leftover >= 10 means a future min-size item still fits.
    if pr >= 10 {
        score -= 5.0;
    } else if pr > 0 {
        score += 6.0; // sub-10 dead space
    }

    // Perfect fit: post_residual == 0 is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Harmonic fraction of capacity used: item_size / bin_capacity in eighths.
    let eighth = (item_size * 8 + bin_capacity / 2) / bin_capacity;
    score -= eighth as f64 * 2.0; // reward large items filling bins

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
            // Harmonic bonus: next item exactly consumes leftover class
            if (pr - next_item_size as i64) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // next item won't fit here; less valuable bin
        }
    } else {
        // Last item: strongly prefer zero waste
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a mild default priority,
    // but should lose to good fits into existing bins.
