    // Dead-space penalty: residuals too small for the next item (or smallest plausible item) are wasted.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        score += 50.0 + (min_useful - post_residual) as f64 * 5.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap unusable by the known next item: strong penalty, worse the closer to full.
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    } else {
