    let mut score = post_residual as f64;

    // Strong base penalty for leaving unusable dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // tiny hole: nearly worthless
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill is best possible
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / 100.0).max(0.0);
        // Penalize if post_residual can't fit the next item (dead space risk).
        if post_residual < next_item_size {
            score += 15.0;
        }
        // Reward chains: post fits next, and next's post residual is also useful.
        let next_post = post_residual as i64 - next_item_size as i64;
        if next_post >= 0 && next_post < 10 {
            score -= 20.0; // two-step perfect chain
        }
    }

    // Compare against mean residual: bins far below mean are "scarce space" bins,
    // use them while we can; bins above mean have room to spare.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins moderately; discount penalty when item is big,
        // fitting options are scarce, or stream is late (fewer future chances).
        score += 35.0 - 25.0 * large_item - 15.0 * scarcity - 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin pairs well with a large next item.
            score -= 0.2 * next_item_size as f64;
        }
    }

    score
}

