pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of the fit: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits strongly (non-linear)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_frac < 0.05 {
        score -= 25.0;
    } else if post_frac < 0.12 {
        score -= 12.0 * (0.12 - post_frac) / 0.12;
    }

    // Penalize leaving awkward dead space that likely can't be filled
    // (dead space is worse when the leftover is small-but-unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a great chain placement -> reward; if next item would be blocked,
    // mild penalty scaled by progress (early on, blocking matters less).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item cannot use this residual: dead space penalty grows over time
            score += 5.0 * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 10.0 * (1.0 - post_frac);
    }

    // New-bin candidate handling: opening a new bin is generally costly,
    // but attractive when the item is large and no open bin fits tightly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying if many bins are open with
        // fragmented residuals (mean residual low => open bins are nearly full)
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut open_cost = 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        open_cost -= 15.0 * fragmentation * progress;
        // Large items fit well in empty bins: reward proportionally
        open_cost -= 18.0 * fill_frac;
        // If the item is huge and only a fresh bin gives a clean fit, favor it
        if item_size >= 70 {
            open_cost -= 10.0;
        }
        score += open_cost;
    }

    // Slight preference to consolidate into bins with low residual (best-fit bias)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild time-dependent exploration noise-free diversification:
    // early in the stream, slightly prefer filling existing bins to keep
    // bin count low; later, prioritize perfect fits (already handled above).
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

